/* @autogenerated */
import { Injectable } from '@angular/core';

/**
 * Variable global donde el host registra, por nombre de remoto, de dónde lee cada microfront su configuración.
 * Antes `_remove_mfa_config_url` (errata).
 */
export const MFE_REMOTES_GLOBAL = '_remote_mfe_config_url';

/** `[url base del remoto, fichero de configuración]`. */
export type MfeRemote = [url: string, file: string];

/**
 * Único punto de acceso a `window` para la configuración y las traducciones de un microfront.
 * Module federation no está operativo (CFG-10): si se descarta, basta con borrar este adaptador y sus usos.
 */
@Injectable({ providedIn: 'root' })
export class MfeConfigAdapter {
  /** Lo llama el host para que el remoto `name` lea su configuración de `url + file`. */
  register(name: string, url: string, file: string): void {
    const remotes = (this.remotes() ?? {}) as Record<string, MfeRemote>;
    remotes[name] = [url, file];
    (window as any)[MFE_REMOTES_GLOBAL] = remotes;
  }

  /** URL de la configuración del remoto `name`; `undefined` si no está registrado (shell, tests). */
  configUrl(name: string): string | undefined {
    const remote = this.remotes()?.[name];
    return remote ? remote[0] + remote[1] : undefined;
  }

  /** Base de las traducciones: la del remoto `name` si está registrado; si no, `i18n` relativo a la app. */
  i18nBase(name: string): string {
    const remote = this.remotes()?.[name];
    return remote ? remote[0] + 'i18n' : 'i18n';
  }

  private remotes(): Record<string, MfeRemote> | undefined {
    return (window as any)[MFE_REMOTES_GLOBAL];
  }
}
